{
  "name": "opencode-content-filter",
  "version": "0.1.1",
  "description": "OpenCode plugin that surfaces provider content-filter finish reasons instead of leaving silent empty turns",
  "type": "module",
  "exports": {
    ".": {
      "import": "./tui.tsx"
    },
    "./tui": {
      "import": "./tui.tsx"
    },
    "./server": {
      "import": "./server.ts"
    }
  },
  "files": [
    "server.ts",
    "tui.tsx",
    "README.md"
  ],
  "scripts": {
    "check": "bun -e \"await import('./tui.tsx'); await import('./server.ts'); console.log('plugin import ok')\""
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "tui",
    "content-filter",
    "moderation",
    "finish-reason",
    "session"
  ],
  "author": "Adam Hassan",
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/Adamkadaban/opencode-content-filter.git"
  },
  "bugs": {
    "url": "https://github.com/Adamkadaban/opencode-content-filter/issues"
  },
  "homepage": "https://github.com/Adamkadaban/opencode-content-filter#readme",
  "engines": {
    "opencode": ">=1.14.22"
  },
  "dependencies": {
    "@opencode-ai/plugin": "latest",
    "@opentui/core": "latest",
    "@opentui/solid": "latest",
    "solid-js": "^1.9.0"
  }
}
